import test from "node:test";
import assert from "node:assert/strict";
import { buildSnapshot, renderMarkdown, renderPinned, renderTurtle } from "../lib/render.js";

const facts = [
	{
		id: "fact_aaaaaaaaaaaa",
		subject: "我",
		subject_id: "self",
		predicate: "allergy",
		object: "花生",
		object_id: null,
		object_kind: "text",
		qualifier: "",
		confidence: 1,
		source: "user",
		observed_at: "2026-11-20T10:00:00.000Z",
		pinned: true,
	},
	{
		id: "fact_bbbbbbbbbbbb",
		subject: "我",
		subject_id: "self",
		predicate: "relation",
		object: "妈妈",
		object_id: "ent_cccccccccccc",
		object_kind: "entity",
		qualifier: "mother",
		confidence: 1,
		source: "model",
		observed_at: "2026-11-21T10:00:00.000Z",
		pinned: false,
	},
];

const overview = {
	counts: { facts: 2, entities: 2, pinned: 1 },
	pinned: [facts[0]],
	recent: facts,
	version: 3,
};

test("pinned text carries the hard constraints and the supersession warning", () => {
	const text = renderPinned(overview.pinned, "2026-11-23T00:00:00.000Z");
	assert.ok(text.includes("allergy = 花生"));
	assert.ok(text.includes("replaces earlier ones"));
	assert.ok(text.length < 2000);
	assert.equal(renderPinned([], "2026-11-23T00:00:00.000Z"), "");
});

test("markdown groups by subject and marks pinned facts", () => {
	const text = renderMarkdown(facts, overview, "2026-11-23T00:00:00.000Z");
	assert.ok(text.startsWith("# 关于我"));
	assert.ok(text.includes("## 我"));
	assert.ok(text.includes("**allergy** = 花生 **硬约束**"));
	assert.ok(text.includes("relation"));
	assert.ok(text.includes("(mother)"));
});

test("turtle is parseable-looking and labels entities", () => {
	const text = renderTurtle(facts, [{ id: "self", kind: "self", name: "我" }], "2026-11-23T00:00:00.000Z");
	assert.ok(text.startsWith("@prefix ex:"));
	assert.ok(text.includes('ex:self a ex:self ;'));
	assert.ok(text.includes('rdfs:label "我"'));
	assert.ok(text.includes("ex:allergy"));
	assert.ok(text.includes('ex:qualifier "mother"'));
});

test("snapshot reports truncation", () => {
	const snapshot = buildSnapshot(facts, overview, null, "2026-11-23T00:00:00.000Z");
	assert.equal(snapshot.version, 3);
	assert.equal(snapshot.facts.length, 2);
	assert.equal(snapshot.truncated, false);
	const truncated = buildSnapshot([facts[0]], { ...overview, counts: { ...overview.counts, facts: 50 } }, null);
	assert.equal(truncated.truncated, true);
});
